insert into public.programs(department_id,code,name,level) select d.id,'btech-'||d.code,'Bachelor of Technology','undergraduate' from public.departments d join public.campuses c on c.id=d.campus_id where c.code='supercampus-main' and d.code<>'mba' on conflict(department_id,code) do update set name=excluded.name;
insert into public.programs(department_id,code,name,level) select d.id,'mba','Master of Business Administration','postgraduate' from public.departments d join public.campuses c on c.id=d.campus_id where c.code='supercampus-main' and d.code='mba' on conflict(department_id,code) do update set name=excluded.name;
